<?php
declare(strict_types=1); namespace App\Modules\Tourism\Models; use App\Core\Database;
final class TourismExperience{private Database $db;public function __construct(){$this->db=app()->get("db");}public function all(int $t,bool $d=false):array{$w=$d?"e.deleted_at IS NOT NULL":"e.deleted_at IS NULL";return $this->db->fetchAll("SELECT e.*,d.name destination_name FROM tourism_experiences e LEFT JOIN tourism_destinations d ON d.id=e.destination_id AND d.tenant_id=e.tenant_id WHERE e.tenant_id=? AND $w ORDER BY e.id DESC",[$t]);}public function find(int $t,int $id,bool $d=false):?array{$w=$d?"e.deleted_at IS NOT NULL":"e.deleted_at IS NULL";return $this->db->fetch("SELECT e.*,d.name destination_name FROM tourism_experiences e LEFT JOIN tourism_destinations d ON d.id=e.destination_id AND d.tenant_id=e.tenant_id WHERE e.tenant_id=? AND e.id=? AND $w LIMIT 1",[$t,$id]);}public function create(int $t,array $d,int $u):int{$this->db->execute("INSERT INTO tourism_experiences(uuid,tenant_id,provider_id,destination_id,title,slug,description,experience_type,duration_minutes,price,max_participants,meeting_point,included,requirements,latitude,longitude,cover_image_path,status,featured,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$t,$d['provider_id'],$d['destination_id'],$d['title'],$d['slug'],$d['description'],$d['experience_type'],$d['duration_minutes'],$d['price'],$d['max_participants'],$d['meeting_point'],$d['included'],$d['requirements'],$d['latitude'],$d['longitude'],$d['cover_image_path'],$d['status'],$d['featured'],$u,$u]);return(int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE tourism_experiences SET provider_id=?,destination_id=?,title=?,slug=?,description=?,experience_type=?,duration_minutes=?,price=?,max_participants=?,meeting_point=?,included=?,requirements=?,latitude=?,longitude=?,cover_image_path=?,status=?,featured=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['provider_id'],$d['destination_id'],$d['title'],$d['slug'],$d['description'],$d['experience_type'],$d['duration_minutes'],$d['price'],$d['max_participants'],$d['meeting_point'],$d['included'],$d['requirements'],$d['latitude'],$d['longitude'],$d['cover_image_path'],$d['status'],$d['featured'],$u,$t,$id]);}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_experiences SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_experiences SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function slugExists(int $t,string $s,?int $id=null):bool{$q="SELECT id FROM tourism_experiences WHERE tenant_id=? AND slug=? AND deleted_at IS NULL";$p=[$t,$s];if($id){$q.=" AND id<>?";$p[]=$id;}return $this->db->fetch($q." LIMIT 1",$p)!==null;}}
